// Idempotency key pattern — safe retries in distributed systems
const crypto = require('crypto');

// ── CLIENT SIDE ──────────────────────────────────────────────
// Derive key deterministically from the logical operation.
// The key is STABLE across retries — same inputs = same key.
function deriveIdempotencyKey(userId, cartId, attemptTimestamp) {
  return crypto
    .createHash('sha256')
    .update(`order:${userId}:${cartId}:${attemptTimestamp}`)
    .digest('hex');
}

async function createOrderWithRetry(userId, cartId, paymentToken) {
  // Fix the timestamp at first attempt — retries use the SAME key
  const firstAttemptTs = Date.now();
  const idempotencyKey = deriveIdempotencyKey(userId, cartId, firstAttemptTs);

  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      const res = await fetch('/api/orders', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Idempotency-Key': idempotencyKey  // same on every retry
        },
        body: JSON.stringify({ userId, cartId, paymentToken }),
        signal: AbortSignal.timeout(5000)
      });
      if (res.ok) return await res.json();
      if (res.status >= 400 && res.status < 500) throw new Error('Client error, no retry');
    } catch (err) {
      if (attempt === 5) throw err;
      // Exponential backoff with jitter
      const base = Math.min(200 * 2 ** attempt, 10000);
      const jitter = Math.random() * base * 0.3;
      await new Promise(r => setTimeout(r, base + jitter));
    }
  }
}

// ── SERVER SIDE ──────────────────────────────────────────────
// Use Redis or a DB table for production; Map here for clarity.
const idempotencyStore = new Map(); // key -> { response, expiresAt }

async function handleCreateOrder(req, res) {
  const key = req.headers['idempotency-key'];
  if (!key) return res.status(400).json({ error: 'Idempotency-Key required' });

  // Return cached response if this key was already processed
  const cached = idempotencyStore.get(key);
  if (cached && cached.expiresAt > Date.now()) {
    return res.status(cached.response.status).json(cached.response.body);
  }

  // Process the order
  const order = await db.createOrder(req.body);
  const responseBody = { orderId: order.id, status: 'created' };

  // Cache for 24 hours — client can retry safely within that window
  idempotencyStore.set(key, {
    response: { status: 201, body: responseBody },
    expiresAt: Date.now() + 24 * 60 * 60 * 1000
  });

  res.status(201).json(responseBody);
}

// Simulating quorum reads and writes
// N=3 replicas, W=2 (write quorum), R=2 (read quorum)
// W + R > N (2+2=4 > 3) => strong consistency

const replicas = [
  { id: 'node-a', data: new Map() },
  { id: 'node-b', data: new Map() },
  { id: 'node-c', data: new Map() }
];

async function quorumWrite(key, value, W = 2) {
  const timestamp = Date.now();
  const writes = replicas.map(async (replica) => {
    // Simulate network: node-c is slow (returns after delay)
    if (replica.id === 'node-c') {
      await new Promise(r => setTimeout(r, 300));
    }
    replica.data.set(key, { value, timestamp });
    return { replicaId: replica.id, ok: true };
  });

  // Collect results as they arrive; stop once quorum is reached
  let acknowledged = 0;
  const results = [];
  for (const write of writes) {
    const result = await write;
    results.push(result);
    acknowledged++;
    if (acknowledged >= W) {
      console.log(`Write quorum (${W}/${replicas.length}) reached for key=${key}`);
      return { ok: true, ackedBy: results.map(r => r.replicaId) };
    }
  }
}

async function quorumRead(key, R = 2) {
  // Read from R replicas and pick the value with the highest timestamp
  const reads = await Promise.all(
    replicas.slice(0, R).map(async (replica) => {
      const entry = replica.data.get(key);
      return { replicaId: replica.id, entry };
    })
  );

  // Resolve: take the most recent write (highest timestamp)
  const best = reads
    .filter(r => r.entry)
    .sort((a, b) => b.entry.timestamp - a.entry.timestamp)[0];

  return best ? best.entry.value : null;
}

// Usage
(async () => {
  await quorumWrite('user:42:name', 'Alice');  // writes to node-a, node-b fast
  const name = await quorumRead('user:42:name');  // reads from node-a, node-b
  console.log('Read:', name); // 'Alice'
})();

// Circuit breaker + exponential backoff with jitter

class CircuitBreaker {
  constructor({ failureThreshold = 5, successThreshold = 2, timeout = 30000 } = {}) {
    this.state = 'CLOSED';      // CLOSED | OPEN | HALF_OPEN
    this.failures = 0;
    this.successes = 0;
    this.failureThreshold = failureThreshold;
    this.successThreshold = successThreshold;
    this.timeout = timeout;
    this.nextAttempt = Date.now();
  }

  async call(fn) {
    if (this.state === 'OPEN') {
      if (Date.now() < this.nextAttempt) {
        throw new Error('Circuit OPEN — fast-fail, protecting downstream');
      }
      this.state = 'HALF_OPEN';
      console.log('Circuit HALF_OPEN — testing downstream...');
    }

    try {
      const result = await fn();
      this.onSuccess();
      return result;
    } catch (err) {
      this.onFailure();
      throw err;
    }
  }

  onSuccess() {
    this.failures = 0;
    if (this.state === 'HALF_OPEN') {
      this.successes++;
      if (this.successes >= this.successThreshold) {
        this.state = 'CLOSED';
        this.successes = 0;
        console.log('Circuit CLOSED — downstream healthy');
      }
    }
  }

  onFailure() {
    this.failures++;
    if (this.state === 'HALF_OPEN' || this.failures >= this.failureThreshold) {
      this.state = 'OPEN';
      this.nextAttempt = Date.now() + this.timeout;
      console.log(`Circuit OPEN — will retry in ${this.timeout}ms`);
    }
  }
}

// Retry with exponential backoff + jitter
async function withRetry(fn, maxAttempts = 5) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      const base = Math.min(100 * 2 ** attempt, 30000);  // cap at 30s
      const jitter = Math.random() * base * 0.3;          // ±30% randomness
      const delay = Math.round(base + jitter);
      console.log(`Attempt ${attempt} failed. Retrying in ${delay}ms...`);
      await new Promise(r => setTimeout(r, delay));
    }
  }
}

// Compose circuit breaker with retry
const breaker = new CircuitBreaker({ failureThreshold: 3, timeout: 10000 });

async function callUserService(userId) {
  return withRetry(() =>
    breaker.call(() =>
      fetch(`https://user-service/users/${userId}`).then(r => r.json())
    )
  );
}
